INSERT INTO packages (id, source_id, schema_version, owner_name, owner_type, satker, package_name, procurement_type, procurement_method, location_raw, budget, selection_date, funding_source, is_umkm, within_country, volume, work_description, specification, potential_waste, severity, reason, is_mencurigakan, is_pemborosan, risk_score, active_tag_count, is_priority, is_flagged, mapped_region_count, inserted_order) VALUES ('65004816', 65004816, 'analyze_legacy', 'Provinsi Sumatera Utara', 'provinsi', 'Dinas Pendidikan', 'Rehabilitasi Ruang Kelas SMAN 1 Babalan', 'Pekerjaan Konstruksi', 'Pengadaan Langsung', 'Sumatera Utara, Langkat (Kab.)', 322245000, 'February 2026', 'APBD', 1, 1, '1 Paket', 'Rehabilitasi Ruang Kelas', 'Ruang lingkup pekerjaan Konstruksi utama terdiri dari: 1. Melakukan pemeriksaan dan penilaian dokumen untuk pelaksanaan konstruksi fisik, baik dari segi kelengkapan maupun segi kebenarannya. 2. Menyusun program kerja yang meliputi jadwal waktu pelaksanaan, jadwal pengadaan bahan, jadwal penggunaan tenaga kerja, dan jadwal penggunaan peralatan berat. 3. Melaksanakan persiapan di lapangan sesuai dengan pedoman pelaksanaan. 4. Menyusun gambar pelaksanaan (shop drawing) untuk pekerjaan-pekerjaan yang memerlukannya. 5. Melaksanakan pekerjaan konstruksi fisik di lapangan sesuai dengan dokumen pelaksanaan. 6. Melaksanakan pelaporan pelaksanaan konstruksi fisik, melalui rapat-rapat lapangan, laporan harian, laporan mingguan, laporan bulanan, laporan kemajuan pekerjaan, laporan persoalan yang timbul atau dihadapi, dan surat-menyurat. 7. Membuat gambar yang sesuai dengan pelaksanaan di lapangan (as built drawing) yang selesai sebelum serah terima pertama, setelah disetujui oleh penyedia jasa konsultansi pengawasan konstruksi dan diketahui oleh penyedia jasa konsultansi perencanaan konstruksi. 8. Melaksanakan perbaikan kerusakan-kerusakan yang terjadi di masa pemeliharaan konstruksi.', 0, 'low', NULL, NULL, NULL, 1, 0, 0, 0, 1, 1882116);
