INSERT INTO packages (id, source_id, schema_version, owner_name, owner_type, satker, package_name, procurement_type, procurement_method, location_raw, budget, selection_date, funding_source, is_umkm, within_country, volume, work_description, specification, potential_waste, severity, reason, is_mencurigakan, is_pemborosan, risk_score, active_tag_count, is_priority, is_flagged, mapped_region_count, inserted_order) VALUES ('65050177', 65050177, 'analyze_legacy', 'Kementerian Pertanian', 'central', 'DIREKTORAT JENDERAL LAHAN DAN IRIGASI PERTANIAN', 'Project Management Office (PMO) Kegiatan Cetak Sawah', 'Jasa Konsultansi', 'Seleksi', 'DKI Jakarta, Jakarta Selatan (Kota)', 4657505000, 'February 2026', 'APBN - RUPIAH MURNI (A)', 1, 1, '1 Paket Kegiatan', 'Project Management Office (PMO) Program Cetak Sawah adalah layanan dukungan pengendalian program yang bertugas mengoordinasikan konsolidasi data, melakukan monitoring–evaluasi, pengendalian mutu dan risiko, serta menyusun pelaporan manajerial lintas wilayah untuk memastikan pelaksanaan Program Cetak Sawah berjalan terarah, terukur, dan akuntabel. PMO menyediakan Management Reporting & Monitoring Internal sebagai media pelaporan berbasis data (Indikator Capaian Program, status isu/risiko, dan action tracker), serta memberikan rekomendasi tindak korektif kepada Direktorat Penyediaan Lahan dalam pengambilan keputusan dan percepatan penyelesaian kendala.', 'Penyedia wajib melaksanakan pekerjaan Project Management Office (PMO) Program Cetak Sawah sebagai layanan dukungan pengendalian pelaksanaan kegiatan yang mencakup penyusunan dan penerapan instrumen pengendalian, konsolidasi serta validasi data pelaksanaan, analisis capaian dan deviasi, pengendalian mutu dan risiko, serta penyusunan pelaporan manajerial lintas wilayah. Dalam pelaksanaannya, Penyedia wajib menyusun SOP dan format baku pengendalian (termasuk data dictionary, issue-log, risk register, action tracker, dan checklist QA/QC), melakukan pengumpulan dan verifikasi data fisik–keuangan–mutu beserta bukti dukung, menyajikan analisis tren dan early warning atas kendala pelaksanaan, serta menyusun laporan berkala (mingguan/bulanan) dan ringkasan eksekutif berbasis Indikator Capaian Program berikut rekomendasi tindak korektif. Selain itu, Penyedia wajib melaksanakan pengendalian kontrak dan biaya melalui telaah progres keuangan serta perubahan pekerjaan (apabila terdapat adendum/CCO) beserta dampaknya, dan melaksanakan QA/QC teknis melalui review dokumen/hasil lapangan secara sampling berbasis risiko sampai dengan penutupan tindak lanjut temuan. Sebagai bagian dari dukungan pelaporan, Penyedia wajib menyediakan Management Reporting & Monitoring Internal dalam bentuk web-based reporting workspace yang dilengkapi pengaturan akses berbasis peran (role-based access control), pencatatan aktivitas (audit trail/logging), dan pengelolaan data terstandar (data governance) untuk menjamin integritas dan akuntabilitas data. Penyedia wajib menyerahkan dokumen kebutuhan dan desain, hasil uji penerimaan pengguna (UAT) beserta berita acara, manual pengguna dan administrator, serta dokumentasi teknis sesuai ketentuan serah terima. Penyedia juga wajib memfasilitasi koordinasi (rapat koordinasi nasional dan rapat teknis wilayah) serta asistensi penerapan standar pelaporan/pengendalian kepada satker/daerah sesuai arahan PPK, dengan seluruh kegiatan didukung dokumentasi resmi (undangan/notulen/daftar hadir) dan menjadi bagian dari eviden pelaksanaan pekerjaan.', 0, 'low', NULL, NULL, NULL, 1, 0, 0, 0, 1, 1885053);
